const state=initialState();
let controller,optionsLoaded=false,detailId=null,detailRequest=0,refreshBusy=false,lastSummaryBacklogAlert=null,lastArchiveHistoryFocus=null;
function params(route,filtered=false){const p=new URLSearchParams({route,period:state.period});if(state.fgDevice)p.set('fg_device',state.fgDevice);if(state.view==='settings'){p.set('settings_tab',state.settingsTab);if(state.settingsDevice)p.set('settings_device',state.settingsDevice);p.set('settings_device_tab',state.settingsDeviceTab||'keys');if(state.setupDevice)p.set('setup_device',state.setupDevice);}if(state.view==='cold')coldBrowseAppend(p);if(state.view==='system'){p.set('system_tab',state.systemTab);if(state.systemFocus)p.set('system_focus',state.systemFocus);p.set('backlog_history_page',state.backlogHistoryPage);p.set('mail_backlog_history_page',state.mailBacklogHistoryPage);archiveTlsHistoryAppend(p);}if(state.period==='custom'){if(state.from)p.set('from',state.from);if(state.to)p.set('to',state.to);}if(state.view==='ports'){for(const[k,v]of Object.entries(state.portFilters))if(v!=='')p.set('port_'+k,v);p.set('port_page',state.portPage);if(state.portGroup){p.set('port_group',state.portGroup);p.set('port_records_page',state.portRecordsPage);}}if(route==='vpn'||state.view==='vpn'){for(const[k,v]of Object.entries(state.vpnFilters))if(v!=='')p.set(k,v);p.set('vpn_page',state.vpnPage);p.set('vpn_log_page',state.vpnLogPage);}if(route==='config_history'||state.view==='history'){for(const[k,v]of Object.entries(state.historyFilters))if(v!=='')p.set(k,v);p.set('history_page',state.historyPage);}if(route==='config_impact'||state.view==='impact'){p.delete('period');p.delete('from');p.delete('to');if(state.impactChange)p.set('impact_change',state.impactChange);p.set('impact_minutes',state.impactMinutes);p.set('impact_direction',state.impactDirection);p.set('impact_tab',state.impactTab);for(const[k,v]of Object.entries(state.impactPages))p.set('impact_'+k+'_page',v);if(state.impactAsOf)p.set('impact_asof',state.impactAsOf);if(state.impactMaxId)p.set('impact_max_id',state.impactMaxId);}if(route==='change_alerts'||state.view==='overview')p.set('alert_page',state.alertPage);if(state.view==='impact'||route==='config_impact'){if(state.impactPinned)p.set('impact_pinned','1');if(state.impactFocus)p.set('impact_focus',state.impactFocus);}if(state.view==='reason'){p.set('reason_ref',state.reasonRef);p.set('reason_scope',state.reasonScope);}if(state.view==='profile'){p.set('profile_name',state.profileName);p.set('profile_module',state.profileModule);p.set('profile_block_scope',state.profileBlockScope);}if(state.view==='policy'){p.set('policy_id',state.policyId);p.set('policy_scope',state.policyScope);p.set('policy_block_scope',state.policyBlockScope);}if(state.view==='target'){p.set('target_key',state.targetKey);p.set('target_scope',state.targetScope);if(state.targetOriginSource)p.set('origin_source',state.targetOriginSource);}if(state.view==='source'){p.set('source_ip',state.sourceIp);p.set('source_scope',state.sourceScope);}if(state.view==='overview')p.set('block_dimension',state.blockDimension);if(state.view==='policies')p.set('policy_tab',state.policyTab);if(state.view==='vpn')p.set('vpn_tab',state.vpnTab);if(state.view==='events')p.set('page',state.page);if(state.view==='allowed'&&typeof allowedAppend==='function')allowedAppend(p);if(filtered){p.set('group_av',state.groupAv?'1':'0');p.set('group_security',state.groupSecurity?'1':'0');p.set('group_traffic',state.groupTraffic?'1':'0');for(const [k,v] of Object.entries(state.filters))if(v!=='')p.set(k,v);}return p;}
function syncUrl(mode='replace'){const p=params('',state.view==='events');p.delete('route');p.set('view',state.view);if(state.view==='archive')archiveLedgerAppend(p);if(state.view==='events')p.set('outcome',state.filters.outcome);if(state.view==='overview')p.set('block_scope',state.blockScope);const url='/?'+p.toString();if(mode==='push'&&url!==location.pathname+location.search){history.replaceState({...history.state,scrollY:window.scrollY},'',location.href);history.pushState({scrollY:0},'',url);}else history.replaceState(history.state,'',url);if(typeof savedEventViewsRender==='function')savedEventViewsRender();}

const API_REQUEST_TIMEOUT_MS=45000;
async function api(route,filtered=false,extra={},signal){
 const device=String(state.fgDevice),p=params(route,filtered),request=new AbortController();
 for(const[k,v]of Object.entries(extra))p.set(k,v);
 let timedOut=false,timer,rejectAbort;
 const current=()=>!signal?.aborted&&!timedOut&&String(state.fgDevice)===device;
 const aborted=()=>new DOMException('İstek kapsamı değişti','AbortError');
 const timeoutError=()=>{const error=new Error('Sunucu zamanında yanıt vermedi. Yeniden deneyin.');error.code='request_timeout';return error;};
 const cancelled=new Promise((_,reject)=>{rejectAbort=reject;});
 const cancel=()=>{request.abort();rejectAbort(aborted());};
 if(signal?.aborted)cancel();else signal?.addEventListener('abort',cancel,{once:true});
 const deadline=new Promise((_,reject)=>{timer=setTimeout(()=>{timedOut=true;request.abort();reject(timeoutError());},API_REQUEST_TIMEOUT_MS);});
 try{
  const operation=(async()=>{
   const r=await fetch('/api.php?'+p,{credentials:'same-origin',signal:request.signal});
   if(!current())throw aborted();
   if(r.status===401){location.href='/';const error=new Error('Oturum sona erdi.');error.code='auth_required';error.status=401;throw error;}
   let data;try{data=await r.json();}catch(error){if(!current())throw aborted();throw new Error('Sunucu yanıtı okunamadı. Yeniden deneyin.');}
   if(!current())throw aborted();
   if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('Sunucu yanıtı okunamadı. Yeniden deneyin.');
   if(data.code==='device_access'){controller?.abort();for(const d of document.querySelectorAll('dialog[open]'))d.close();location.replace('/?view=overview');throw new DOMException('Erişim değişti','AbortError');}
   if(!r.ok){const error=new Error(data.error||'Veriler yüklenemedi.');error.code=typeof data.code==='string'?data.code:'';error.status=r.status;throw error;}
   return data;
  })();
  return await Promise.race([operation,deadline,cancelled]);
 }catch(error){if(signal?.aborted||String(state.fgDevice)!==device)throw aborted();if(timedOut)throw timeoutError();throw error;}
 finally{clearTimeout(timer);signal?.removeEventListener('abort',cancel);}
}
async function apiWrite(route,body,signal,validate){
 const request=new AbortController(),aborted=()=>new DOMException('İstek kapsamı değişti','AbortError');
 if(signal?.aborted)throw aborted();
 let timer,rejectAbort,timedOut=false,started=false,known=false;
 const cancelled=new Promise((_,reject)=>{rejectAbort=reject;});
 const cancel=()=>{request.abort();rejectAbort(aborted());};
 signal?.addEventListener('abort',cancel,{once:true});
 const deadline=new Promise((_,reject)=>{timer=setTimeout(()=>{timedOut=true;request.abort();reject(new Error('Sunucu zamanında yanıt vermedi.'));},API_REQUEST_TIMEOUT_MS);});
 try{
  const operation=(async()=>{
   started=true;
   const response=await fetch('/api.php?'+new URLSearchParams({route}),{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':$('meta[name="csrf-token"]').content},body,signal:request.signal});
   if(signal?.aborted||timedOut)throw aborted();
   if(response.status===401){known=true;location.href='/';const error=new Error('Oturum sona erdi.');error.status=401;throw error;}
   const data=await response.json();
   if(signal?.aborted||timedOut)throw aborted();
   if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('Sunucu yanıtı okunamadı.');
   if(!response.ok){known=response.status>=400&&response.status<500&&response.status!==408;const error=new Error(data.error||'İşlem tamamlanamadı.');error.status=response.status;error.data=data;throw error;}
   if(validate&&validate(data)!==true)throw new Error('Yazım yanıtı doğrulanamadı.');
   known=true;
   return data;
  })();
  return await Promise.race([operation,deadline,cancelled]);
 }catch(error){
  if(started&&!known){
   error=signal?.aborted?aborted():new Error((timedOut?'Sunucu zamanında yanıt vermedi. ':'')+'İsteğin sonucu doğrulanamadı. İşlem otomatik tekrarlanmadı; güncel durumu yükleyin.');
   error.ambiguous=true;if(error.name!=='AbortError')error.code='write_unconfirmed';
  }
  throw error;
 }finally{clearTimeout(timer);signal?.removeEventListener('abort',cancel);}
}
async function optionalLicensedApi(route,signal){
 try{return await api(route,false,{},signal);}
 catch(error){if(error.status===402&&error.code==='license_restricted')return {license_restricted:true,components:{}};throw error;}
}
async function systemFortigateLive(signal){
 if(!managementConnections.length)return {components:{},device_unassigned:true};
 try{return await api('fortigate_live',false,{},signal);}
 catch(error){if(error.code==='license_restricted')return {components:{},license_restricted:true};throw error;}
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),4500);}
function empty(text='Seçili aralıkta kayıt bulunamadı.'){return `<div class="empty-state">${esc(text)}</div>`;}
function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr class="table-empty"><td colspan="${headers.length}">Seçili filtrelerle kayıt bulunamadı.</td></tr>`}</tbody></table>`;}
function metric(label,value,note,ico,color=''){return `<article class="metric-card ${color}"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom">${note}</div></article>`;}
function outcomeTag(e){if(e.outcome==='security_block')return '<span class="tag block">● Engellendi</span>';if(e.utm_action==='block')return '<span class="tag block">UTM: engel</span>';if(e.outcome==='local_deny'||e.outcome==='policy_deny')return '<span class="tag deny">● Reddedildi</span>';if(Number(e.rating_error))return '<span class="tag medium">● Sorgu hatası</span>';return `<span class="tag ${['pass','passthrough','accept','permit'].includes(e.action)?'pass':'info'}">${esc(e.action||'Gözlem')}</span>`;}
function drawFlow(series){
 if(!series.length){$('#flow-chart').innerHTML=empty();return;}
 const width=720,height=180,left=42,right=12,top=14,bottom=29,w=width-left-right,h=height-top-bottom;
 const totalMax=Math.max(...series.map(s=>Number(s.total)),1),blockMax=Math.max(...series.map(s=>Number(s.blocks)),1);
 const step=w/series.length,bar=Math.max(2,Math.min(step*.55,34));let svg='';
 for(let i=0;i<4;i++){const y=top+h*i/3;svg+=`<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" stroke="#edf1f6"/><text x="${left-9}" y="${y+3}" text-anchor="end" fill="#a7b2c0" font-size="8">${compact(totalMax*(1-i/3))}</text>`;}
 let path='';series.forEach((s,i)=>{const x=left+(i+.5)*step,y=top+h*(1-Number(s.total)/totalMax);const label=trTime(s.hour,true);svg+=`<rect x="${x-bar/2}" y="${y}" width="${bar}" height="${Math.max(1,top+h-y)}" rx="2" fill="#9bb3d6" opacity=".75"><title>${esc(label)} — ${num(s.total)} kayıt, ${num(s.blocks)} güvenlik engeli</title></rect>`;const py=top+h*(1-Number(s.blocks)/blockMax*.75);path+=(i?' L':'M')+x+','+py;if(series.length<16||i%Math.ceil(series.length/8)===0){const d=parseTime(s.hour);const label=series.length>30?d.toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul',day:'2-digit',month:'2-digit'}):d.toLocaleTimeString('tr-TR',{timeZone:'Europe/Istanbul',hour:'2-digit',minute:'2-digit'});svg+=`<text x="${x}" y="${height-8}" text-anchor="middle" fill="#9ba8b9" font-size="8">${esc(label)}</text>`;}});
 svg+=`<path d="${path}" fill="none" stroke="#dba879" stroke-width="1.8" stroke-linejoin="round"/>`;
 $('#flow-chart').innerHTML=`<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="Saatlik toplam kayıtlar sütunlarla, güvenlik engelleri ayrı ölçekte çizgiyle gösterilir.">${svg}</svg>`;
 $('#chart-scope').textContent=`${trTime(series[0].hour,true).replace(/:\d\d$/,'')} — ${trTime(series.at(-1).hour,true).replace(/:\d\d$/,'')}`;
 $('#flow-chart').title='Sütunlar toplam kayıt hacmini, çizgi engellerin kendi ölçeğindeki eğilimini gösterir. Nokta ayrıntıları için sütun üzerinde bekleyin.';
}
function renderModules(rows){const total=rows.reduce((n,r)=>n+Number(r.n),0);$('#module-chart').innerHTML=total?`<div class="stacked-bar">${rows.map(r=>`<span style="width:${Number(r.n)/total*100}%;background:${moduleColors[r.label]||'#aaa'}"></span>`).join('')}</div><div class="module-list">${rows.map(r=>`<div class="module-row"><span class="module-dot" style="background:${moduleColors[r.label]||'#aaa'}"></span><span class="module-name">${esc(moduleNames[r.label]||r.label)}</span><b>${num(r.n)}</b><small>${(Number(r.n)/total*100).toLocaleString('tr-TR',{maximumFractionDigits:1})}%</small></div>`).join('')}</div>`:empty('Güvenlik engeli bulunamadı.');}
