 return `<section class="av-group-card ${kind}-group-card"><div class="av-group-heading"><h3>${esc(heading)} grubu</h3><span class="group-count">${num(group.total_records)} kayıt</span></div><p>${group.key_complete?(traffic?'Aynı kaynak IP, hedef, policy ve ret gerekçesi.':i.module==='ips'?'Aynı kaynak IP, hedef, policy, profil ve saldırı imzası.':'Aynı kaynak IP, hedef, policy, profil ve engelleme gerekçesi.'):'Grup bilgileri eksik; bu olay ayrı tutulur.'}</p><div class="security-group-facts"><div><small>KAYNAK → HEDEF</small><strong>${esc(i.source)} → ${esc(endpoint(i.target,i.port))}</strong></div><div><small>${traffic?'POLICY / KAPSAM':'POLICY → PROFİL'}</small><strong>#${esc(i.policyid)} ${traffic?'· '+esc(i.policytype||i.outcome):'→ '+esc(i.profile)}</strong></div><div><small>ENGELLEME GEREKÇESİ</small><strong>${esc(securityReason(i))}</strong></div>${extra}</div><p class="note-help">${esc(help)} Port, protokol, cihaz/VDOM ve policy UUID de ayrı tutulur.</p><div class="group-times">Tüm arşiv · İlk: ${esc(trTime(group.first_event_at,true))}<br>Son: ${esc(trTime(group.last_event_at,true))}</div><details id="${prefix}-members"><summary>Gruptaki tüm kayıtları göster</summary><p class="note-help">Bu liste tüm arşivi kapsar.</p><div id="${prefix}-table"></div><div class="group-pagination"><button type="button" id="${prefix}-prev" class="button">← Önceki</button><span id="${prefix}-page-label"></span><button type="button" id="${prefix}-next" class="button">Sonraki →</button></div></details></section>`;
