 root.innerHTML=`<a class="summary-backlog-card ${fresh?'':'is-uncertain'}" href="/?${esc(p.toString())}" id="summary-backlog-open"><span class="summary-backlog-icon">${icon('alert')}</span><div class="summary-backlog-copy"><strong class="summary-backlog-title">Özet indeksinde uzun süren birikme${fresh?'':' · güncel ölçüm bekleniyor'}</strong><p><b>${measured(count,' kayıt',0)}</b> ${fresh?'işlenmeyi bekliyor':'son doğrulanan bekleyen sayı'} · İlk gözlenen: ${esc(trTime(alert.started_at,true))} · Tepe: ${measured(alert.peak_pending,' kayıt',0)}</p><small>${fresh?`Eşik: en az ${measured(alert.rule?.minimum_pending,' kayıt',0)} · ${measured((alert.rule?.minimum_seconds||0)/60,' dakika',0)}. Bekleyen sayı sıfıra indiğinde uyarı otomatik kalkar.`:`Son doğrulama: ${esc(trTime(alert.last_confirmed_at,true))}. Kuyruğun boşaldığı henüz doğrulanamadı.`} Canlı izleme; tarih filtresinden bağımsızdır.</small></div><span class="summary-backlog-action">Birikme grafiğini aç →</span></a>`;
