 const rows=episodes.map(r=>`<tr><td>${esc(trTime(r.start,true))}${r.start_bounded?'':'<small>Başlangıç daha erken olabilir</small>'}</td><td>${r.end?esc(trTime(r.end,true)):'—'}</td><td>${measured(r.peak,'',0)}</td><td><span class="tag ${r.status==='drained'?'pass':r.status==='gap'?'medium':'info'}">${r.status==='drained'?'Boşaldı':r.status==='gap'?'Ölçüm kesintisi':'Aralığın son örneğinde bekliyor'}</span></td></tr>`);
