function renderSystemBase(d){const maintenance=typeof maintenanceData!=='undefined'&&maintenanceData?maintenanceData:d.maintenance;const actual=maintenance?.fresh===true&&maintenance?.available===true?maintenance.worker?.collector_state:null;const c=d.collector,l=c.log_ingestion||{},q=l.stats?.fortigate||{},action=l.stats?.fg_raw_archive||{},v=(c.volumes?.data?.report||[]).flatMap(report=>report.lv||[]).find(row=>row.lv_name==='fortigate-data')||{};const hybrid=c.storage?.mode==='hybrid',systemDisk=(c.disks||[]).find(row=>row.role==='system'),depotDisk=(c.disks||[]).find(row=>row.role==='depot');const storage=hybrid?'SSD + HDD · ayrı sistem ve depo diskleri':c.storage?.mode==='system-root'?'SSD · sistem diski':v.segtype==='linear'?'Tek disk · aynalama kapalı':v.segtype?(v.segtype+(/^raid/.test(v.segtype)||v.segtype==='mirror'?' · '+(v.copy_percent||'—')+'%':'')):'Bilinmiyor';$('#system-content').innerHTML=`<div class="system-grid"><section class="panel"><div class="panel-heading"><h2>Log alımı ve indeksleme</h2><span class="tag pass">Canlı ölçüm</span></div><div class="system-list">${systemLine(actual?'Log alıcısı · güncel durum':'Log alıcısı · son sağlık örneği',esc(actual?({active:'Çalışıyor',inactive:'Kapalı',failed:'Başarısız',activating:'Başlatılıyor',deactivating:'Durduruluyor',unknown:'Bilinmiyor'})[actual]||'Bilinmiyor':c.collector?.data||'Bilinmiyor'))}${systemLine('Dinleme adresi',esc(d.receiver?.listen_ip||d.instance?.collector_ip||'Bilinmiyor')+':5514 / TCP')}${systemLine('İzinli kaynaklar',d.receiver?.allowed_ips?.map(esc).join(', ')||'Bilinmiyor')}${systemLine('Eski sağlık örneğinde kuyruk',measured(l.queue_checkpoint_pending,' kayıt',0))}${systemLine('Arşiv yazma hatası',num(action.failed))}${systemLine('Atılan kayıt',num(Number(q['discarded.full']||0)+Number(q['discarded.nf']||0)))}${systemLine('Son arşiv olayının yaşı',measured(l.archive_event_lag_seconds,' sn'))}${systemLine('Web indeksindeki son olay',esc(trTime(d.latest_event?.event_at,true)))}${systemLine('İndekslenen satır',num(d.index.lines))}${systemLine('Parser ret sayısı',num(d.index.invalid_rows))}</div></section><section class="panel"><div class="panel-heading"><h2>Depolama ve sunucu</h2><span data-icon="server"></span></div><div class="system-list">${systemLine('Veri alanı',esc(c.data_mounted?'Bağlı':'BAĞLI DEĞİL'))}${systemLine('Depolama düzeni',esc(storage))}${hybrid?systemLine('Sistem diski',esc('SSD'+(systemDisk?.serial?' · '+systemDisk.serial:'')))+systemLine('Log ve yedek diski',esc('HDD'+(depotDisk?.serial?' · '+depotDisk.serial:'')))+systemLine('SSD kapasitesi / boş alan',bytes(c.system_disk_space?.total)+' / '+bytes(c.system_disk_space?.free))+systemLine('Geçici teslim kuyruğu',c.storage.queue_location==='system'?'SSD · 10 GB kuyruk sınırı':'HDD · 10 GB kuyruk sınırı'):''}${systemLine(hybrid?'HDD kapasitesi':'Toplam kapasite',bytes(c.disk_space?.total))}${systemLine('Kullanılan',bytes(c.disk_space?.used))}${systemLine('Boş alan',bytes(c.disk_space?.free))}${systemLine('Saat eşitleme (NTP)',esc(c.ntp_synchronized?.data||'Bilinmiyor'))}${hybrid?systemLine('Ham log, arşiv ve yedekler',esc(c.storage.depot_path))+systemLine('MariaDB ve aranabilir indeks','SSD · sistem diski'):systemLine('Ham arşiv / MariaDB',esc(d.instance?.data_path||'/srv/fls-server')+' · '+esc(d.instance?.storage_label||v.segtype||'Depolama türü bilinmiyor'))}${systemLine('Web altyapısı','nginx '+esc(d.software?.nginx||'—')+' · PHP '+esc(d.software?.php||'—'))}${systemLine('Veritabanı',esc(d.software?.mariadb||'—'))}${systemLine('Kontrol zamanı',esc(trTime(c.checked_at,true)))}</div></section></div><div class="info-strip" style="margin-top:20px"><span data-icon="shield"></span><p>Ham kayıtlar, aranabilir indeks ve imza manifestleri ayrı saklanır. Aynalı disk depolaması bağımsız yedek yerine geçmez. İmzalama ve harici yedeklerin güncel durumu Arşiv bütünlüğü ekranından izlenir.</p></div>`;paintIcons($('#system-content'));}
async function health(){if(typeof maintenanceRefresh==='function')maintenanceRefresh();if(document.documentElement.dataset.userRole!=='admin')return;try{const d=await api('health');const c=d.collector;if(typeof maintenanceAccept==='function')maintenanceAccept(d.maintenance);const good=c.collector?.data==='active' && Date.now()-Date.parse(c.checked_at)<5*60*1000;$('#collector-dot').classList.toggle('bad',!good);$('#collector-text').textContent=good?'Log alıcısı çalışıyor':'Alıcı kontrol edilmeli';if(typeof maintenanceRender==='function')maintenanceRender();const i=d.index,ratio=Number(i.observed_bytes)?Number(i.indexed_bytes)/Number(i.observed_bytes):0;const banner=$('#index-banner');banner.classList.toggle('hidden',ratio>.999&&Number(i.invalid_rows)===0);if(ratio<=.999)banner.textContent=`Arşiv indeksi hazırlanıyor · ${num(i.lines)} kayıt · ${Math.min(100,ratio*100).toLocaleString('tr-TR',{maximumFractionDigits:1})}% tamamlandı. Kayıtlar işleniyor; geçmiş aralıklar tamamlandıkça sayılar güncellenir.`;else if(Number(i.invalid_rows))banner.textContent=`Parser ${num(i.invalid_rows)} satırı indeksleyemedi. Ham kayıtlar korunuyor; servis günlüğü incelenmeli.`;return d;}catch(e){if(e.name!=='AbortError')console.error(e);}}
async function loadOptions(signal){const device=state.fgDevice;if(optionsLoaded===device)return;const d=await api('options',false,{},signal);if(state.fgDevice!==device)return;for(const [name,rows,key,label] of [['policy',d.policies,'policyid',r=>r.policyid+' · '+r.name],['profile',d.profiles,'profile',r=>r.profile],['module',d.modules,'subtype',r=>moduleNames[r.subtype]||r.subtype]]){const select=$('#filter-'+name);while(select.options.length>1)select.remove(1);for(const r of rows){const o=document.createElement('option');o.value=r[key];o.textContent=label(r);select.append(o);}}optionsLoaded=device;syncFilters();}
